def bellman_ford(vertices, edges, start):
    distance = {vertex: float("inf") for vertex in vertices}
    previous = {vertex: None for vertex in vertices}
    distance[start] = 0

    for _ in range(len(vertices) - 1):
        updated = False
        for source, target, weight in edges:
            if distance[source] == float("inf"):
                continue
            candidate = distance[source] + weight
            if candidate < distance[target]:
                distance[target] = candidate
                previous[target] = source
                updated = True
        if not updated:
            break
    return distance, previous

def has_reachable_negative_cycle(distance, edges):
    for source, target, weight in edges:
        if distance[source] == float("inf"):
            continue
        if distance[source] + weight < distance[target]:
            return True
    return False

